        {
          "chunk_id": "PG-000008042426000103-0007",
          "quote": "We create, manufacture, market and distribute a diversified portfolio of daily-use products"
        },
        {
          "chunk_id": "PG-000008042426000103-0079",
          "quote": "Fabric & Home Care: This segment is comprised of a variety of fabric care products, including laundry detergents, additives and fabric enhancers"
        },
        {
          "chunk_id": "PG-000008042426000103-0079",
          "quote": "Baby, Feminine & Family Care: In baby care, we are a global market leader"
        }
      ]
    },
    {
      "kind": "qualitative",
      "text": "In fabric care, the Company generally holds the number one or number two market share position and is the global market leader with over 35% market share, while its global home care market share is more than 30% across the categories in which it competes.",
      "citations": [
        {
          "chunk_id": "PG-000008042426000103-0079",
          "quote": "In fabric care, we generally have the number one or number two market share position and are the global market leader with over 35% market share"
        },
        {
          "chunk_id": "PG-000008042426000103-0079",
          "quote": "Our global home care market share is more than 30% across the categories in which we compete"
        }
      ]
    },
    {
      "kind": "qualitative",
      "text": "The Company is also a global market leader in baby care with more than 30% global market share and in feminine care with nearly 30% global market share.",
      "citations": [
        {
          "chunk_id": "PG-000008042426000103-0079",
          "quote": "In baby care, we are a global market leader and compete mainly in taped diapers, pants and baby wipes, with more than 30% global market share."
        },
        {
          "chunk_id": "PG-000008042426000103-0079",
          "quote": "We are the global market leader in the feminine care category with nearly 30% global market share."
        }
      ]
    },
    {
      "kind": "qualitative",
      "text": "Products are sold through multiple retail and digital channels, with Walmart Inc. and its affiliates representing approximately 16% of total sales, no other customer representing more than 10%, and the top ten customers accounting for approximately 43% of total net sales in {{p:FY0}} and {{p:FY-1}}.",
      "citations": [
        {
          "chunk_id": "PG-000008042426000103-0075",
          "quote": "Our products are sold in about 180 countries and territories primarily through mass merchandisers, digital commerce (including social commerce) channels, grocery stores, membership club stores"
        },
        {
          "chunk_id": "PG-000008042426000103-0008",
          "quote": "Sales to Walmart Inc. and its affiliates represent approximately 16% of our total sales"
        },
        {
          "chunk_id": "PG-000008042426000103-0008",
          "quote": "No other customer represents more than 10% of our total sales"
        },
        {
          "chunk_id": "PG-000008042426000103-0008",
          "quote": "Our top ten customers accounted for approximately 43% of our total net sales"
        }
      ]
    }
  ]
}

