{
  "claims": [
    {
      "kind": "quantitative",
      "text": "Liquidity coverage was {{m:liquidity_coverage:FY0}} for {{p:FY0}} and {{m:liquidity_coverage:LTM}} for {{p:LTM}}, indicating that listed liquidity sources covered listed needs in both periods.",
      "citations": []
    },
    {
      "kind": "quantitative",
      "text": "For {{p:LTM}}, listed sources included {{m:cash:LTM}} of cash and cash equivalents and {{m:cfo:LTM}} of cash from operations, while listed needs included {{m:short_term_debt:LTM}} of short-term debt, {{m:capex:LTM}} of capital expenditures and {{m:dividends:LTM}} of dividends paid.",
