        {
          "chunk_id": "PG-000008042426000103-0117",
          "quote": "These facilities are currently undrawn and we anticipate that they will remain undrawn."
        }
      ]
    },
    {
      "kind": "qualitative",
      "text": "Management anticipates being able to support short-term liquidity and operating needs largely through cash generated from operations.",
      "citations": [
        {
          "chunk_id": "PG-000008042426000103-0116",
          "quote": "We anticipate being able to support our short-term liquidity and operating needs largely through cash generated from operations."
        }
      ]
    },
    {
      "kind": "qualitative",
      "text": "The Company has agreements with a diverse group of financial institutions that, if needed, should provide sufficient funding to meet short-term financing requirements.",
      "citations": [
        {
          "chunk_id": "PG-000008042426000103-0116",
          "quote": "we have agreements with a diverse group of financial institutions that, if needed, should provide sufficient funding to meet short-term financing requirements."
        }
      ]
    }
  ]
}

{
  "claims": [
    {
      "kind": "quantitative",
      "text": "In {{p:FY0}}, debt maturing in the next twelve months is {{m:maturity_year_1:FY0}}, in year two {{m:maturity_year_2:FY0}}, in year three {{m:maturity_year_3:FY0}}, in year four {{m:maturity_year_4:FY0}}, and in year five {{m:maturity_year_5:FY0}}, while debt maturing after year five is {{m:maturity_after_year_5:FY0}}.",
      "citations": []
    },
    {
      "kind": "quantitative",
      "text": "Debt due within 24 months totals {{m:debt_due_24m:FY0}}, or {{m:share_due_24m:FY0}} of total debt, and near-term maturity cover is {{m:near_term_maturity_cover:FY0}}.",
      "citations": []
    },
    {
      "kind": "qualitative",
      "text": "In {{p:FY0}}, the company maintained an $8.0 billion bank credit facility split between a $3.2 billion five-year facility and a $4.8 billion 364-day facility, and these facilities were undrawn and expected to remain undrawn.",
      "citations": [
        {
          "chunk_id": "PG-000008042426000103-0117",
          "quote": "The current facility is an $8.0 billion facility split between a $3.2 billion five-year facility and a $4.8 billion 364-day facility, which expire in October 2030 and October 2026, respectively."
        },
        {
          "chunk_id": "PG-000008042426000103-0228",
          "quote": "These facilities are currently undrawn and we anticipate that they will remain undrawn."
        }
      ]
    },
    {
      "kind": "qualitative",
      "text": "These credit facilities do not have cross-default or ratings triggers, nor do they have material adverse events clauses, except at the time of signing.",
      "citations": [
        {
          "chunk_id": "PG-000008042426000103-0117",
          "quote": "These credit facilities do not have cross-default or ratings triggers, nor do they have material adverse events clauses, except at the time of signing."
        }
      ]
    },
    {
      "kind": "qualitative",
      "text": "In {{p:FY0}}, current liabilities exceeded current assets by $12.5 billion, but the company anticipated being able to support short-term liquidity and operating needs largely through cash generated from operations.",
      "citations": [
        {
          "chunk_id": "PG-000008042426000103-0116",
          "quote": "At June 30, 2026, our current liabilities exceeded current assets by $12.5 billion, largely due to accounts payable, short-term borrowings and debt due within one year."
        },
        {
          "chunk_id": "PG-000008042426000103-0116",
          "quote": "We anticipate being able to support our short-term liquidity and operating needs largely through cash generated from operations."
        }
      ]
    },
    {
      "kind": "qualitative",
      "text": "The company stated that strong short- and long-term debt ratings have enabled and should continue to enable it to refinance debt as it becomes due in commercial paper and bond markets.",
      "citations": [
        {
          "chunk_id": "PG-000008042426000103-0116",
          "quote": "We have strong short- and long-term debt ratings, that have enabled and should continue to enable us to refinance our debt as it becomes due in commercial paper and bond markets."
        }
      ]
    }
  ]
}

